package com.example.starter.domain;

/**
 * 工序卡状态机。
 *
 * <p>正常流转：{@link #DISPATCHED} 派工 → {@link #TIGHTENED} 全部紧固点力矩合格
 * → {@link #INSPECTED} 自检互检完成 → {@link #WAITING_WITNESS} 见证缺席等待
 * → {@link #WITNESSED} H 点见证到场 → {@link #ARCHIVED} 放行归档（终态）。
 *
 * <p>{@link #ESCALATED} 等待满 2 小时升级；{@link #QUARANTINED} 返工 2 次后仍超差，整批隔离评审。
 */
public enum CardStatus {
    /** 已派工，力矩紧固进行中。 */
    DISPATCHED,
    /** 全部紧固点最近一次力矩测量合格。 */
    TIGHTENED,
    /** 自检、互检完成且签署人不同。 */
    INSPECTED,
    /** H 点见证缺席，转入等待。 */
    WAITING_WITNESS,
    /** H 点见证人已到场签署。 */
    WITNESSED,
    /** 见证等待满 2 小时（含恰满 2 小时）已升级。 */
    ESCALATED,
    /** 同一紧固点返工 2 次后仍超差，整批隔离评审。 */
    QUARANTINED,
    /** 已放行归档，终态。 */
    ARCHIVED
}

package com.example.starter.domain;

/**
 * 见证链单条事件状态。
 */
public enum WitnessStatus {
    /** 见证缺席，随即转等待。 */
    ABSENT,
    /** 等待见证人到场。 */
    WAITING,
    /** 见证人到场签署。 */
    PRESENT,
    /** 等待满 2 小时（含边界）升级。 */
    ESCALATED
}

package com.example.starter.support;

/**
 * 业务异常：携带 HTTP 状态码与错误码，由全局异常处理统一转响应。
 */
public class ApiException extends RuntimeException {

    private final int status;
    private final String errorCode;

    public ApiException(int status, String errorCode, String message) {
        super(message);
        this.status = status;
        this.errorCode = errorCode;
    }

    public int getStatus() {
        return status;
    }

    public String getErrorCode() {
        return errorCode;
    }

    public static ApiException badRequest(String code, String message) {
        return new ApiException(400, code, message);
    }

    public static ApiException conflict(String code, String message) {
        return new ApiException(409, code, message);
    }

    public static ApiException unprocessable(String code, String message) {
        return new ApiException(422, code, message);
    }

    public static ApiException notFound(String code, String message) {
        return new ApiException(404, code, message);
    }
}

package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时钟配置：默认系统 UTC 时钟；测试可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

