package com.example.starter.api.dto;

import java.math.BigDecimal;
import java.util.List;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;

/**
 * 派工请求：创建工序卡及其紧固点工艺定义。
 *
 * @param fasteners 紧固点列表，力矩标称值单位 N·m；允差缺省 ±5%
 */
public record DispatchRequest(
        @NotBlank String requestId,
        @NotBlank String cardNo,
        @NotBlank String station,
        @NotBlank String productSn,
        @NotNull @Pattern(regexp = "[HN]") String witnessPoint,
        @NotBlank String operator,
        @NotNull List<FastenerSpec> fasteners) {

    /**
     * 紧固点工艺规格。
     */
    public record FastenerSpec(
            @NotBlank String pointCode,
            @NotNull @Positive BigDecimal nominalTorque,
            @Positive BigDecimal tolerancePct) {
    }
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.math.BigDecimal;

/**
 * 力矩紧固测量请求（也用于归档后迟到测量，迟到时仅记录事件）。
 */
public record TorqueRequest(
        @NotBlank String requestId,
        @NotBlank String cardNo,
        @NotBlank String pointCode,
        @NotNull @Positive BigDecimal measuredTorque,
        @NotBlank String operator,
        @NotBlank String toolCode) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 自检互检签署请求：自检人与互检人必须不同。
 */
public record InspectionRequest(
        @NotBlank String requestId,
        @NotBlank String cardNo,
        @NotBlank String selfInspector,
        @NotBlank String mutualInspector) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

/**
 * H 点见证请求：PRESENT 见证人到场；ABSENT 见证缺席（转等待）。
 */
public record WitnessRequest(
        @NotBlank String requestId,
        @NotBlank String cardNo,
        @NotNull @Pattern(regexp = "PRESENT|ABSENT") String action,
        String witnessName) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 进入覆盖工序请求：仅当 H 点已见证到场才允许。
 */
public record CoverageRequest(
        @NotBlank String requestId,
        @NotBlank String cardNo,
        @NotBlank String nextOperation) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 放行归档请求：归档为终态，重复归档幂等成功。
 */
public record ReleaseRequest(
        @NotBlank String requestId,
        @NotBlank String cardNo,
        @NotBlank String releasedBy) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.LocalDate;

/**
 * 力矩工具登记（合成数据）：calibrationDate 为 UTC 日校验日期，仅当日有效。
 */
public record ToolRegisterRequest(
        @NotBlank String toolCode,
        @NotNull LocalDate calibrationDate) {
}

